#!/usr/bin/env python3
"""IPTH MES Agent DevKit v1 installer.

Place this file in ~/IPTH_Traceability/Interplex_MES_FE/.
From BE:
    python ../Interplex_MES_FE/IPTH_AgentDevKit_Updater_v1.py --scan
    python ../Interplex_MES_FE/IPTH_AgentDevKit_Updater_v1.py --apply
    python ../Interplex_MES_FE/IPTH_AgentDevKit_Updater_v1.py --rollback

Only creates docs/mes_agent and developer_tools. NO application code or DB changes.
"""
from __future__ import annotations
import argparse
import base64
import datetime as dt
import hashlib
import io
import json
import os
import sys
import tempfile
import zipfile
from pathlib import Path

PATCH_ID = "agent-devkit-v1-20261107"
BUNDLE = ""


def sha(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def root_from(start: Path) -> Path:
    for p in (start, *start.parents):
        if (p / "Interplex_MES_FE").is_dir() and (p / "Interplex_MES_BE").is_dir():
            return p.resolve()
    raise RuntimeError("Project root not found. Run from Interplex_MES_BE")


def load_files(root):
    payload = {}
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(BUNDLE))) as f:
        for name in f.namelist():
            if not (name.startswith("Interplex_MES_FE/docs/mes_agent/") or name.startswith("Interplex_MES_FE/developer_tools/")):
                raise RuntimeError("Bundle contains unexpected file: " + name)
            destination=(root / name).resolve()
            if not destination.is_relative_to(root):
                raise RuntimeError("Bundle tries to escape root: " + name)
            payload[name]=f.read(name)
    return payload


def classify(root, files):
    states = {}
    for rel, data in sorted(files.items()):
        dest = root / rel
        if dest.is_symlink() or not dest.parent.resolve().is_relative_to(root):
            states[rel] = 'BLOCKED (symlink)'
        elif not dest.exists():
            states[rel] = 'CREATE'
        elif dest.is_file() and dest.read_bytes() == data:
            states[rel] = 'ALREADY'
        else:
            states[rel] = 'CONFLICT'
    return states


def show(root, files, states):
    print('IPTH MES Agent DevKit v1 | project:', root)
    print('SCAN is read-only; runtime application modules and database are not touched.')
    print('\nMARKDOWN AND TOOLS TO INSTALL:')
    for rel, status in states.items():
        header=''
        if rel.endswith('.md'):
            first=files[rel].decode('utf-8').splitlines()[0]
            header=' | '+first.lstrip('# ').strip()
        print(f'  {status:18s} {rel}{header}')
    print('\nSummary:', json.dumps({s:list(states.values()).count(s) for s in sorted(set(states.values()))}))
    print('Safe backup/journal location:', Path.home()/'.ipth_mes_updater_backups'/PATCH_ID)
    return 2 if any(s.startswith('CONFLICT') or s.startswith('BLOCKED') for s in states.values()) else 0


def atomic_write(path, data):
    path.parent.mkdir(parents=True,exist_ok=True)
    fd,tmp=tempfile.mkstemp(prefix='.ipth-devkit-',dir=str(path.parent))
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp,path)
    finally:
        if os.path.exists(tmp): os.unlink(tmp)


def do_apply(root, files, states):
    if show(root, files, states):
        raise RuntimeError('Conflicts detected; no files changed.')
    if all(v=='ALREADY' for v in states.values()):
        print('Already installed. No changes.')
        return
    backup=Path.home()/'.ipth_mes_updater_backups'/PATCH_ID
    if backup.exists():
        raise RuntimeError(f'Backup/journal already exists; refusing unexpected second install: {backup}')
    backup.mkdir(parents=True,mode=0o700)
    created=[]
    try:
        for rel, data in files.items():
            if states[rel]=='CREATE':
                dest = root / rel
                atomic_write(dest,data)
                created.append(rel)
        record={'id':PATCH_ID, 'created':created, 'files':{rel:sha(value) for rel,value in files.items()}}
        atomic_write(backup/'journal.json', json.dumps(record,indent=2).encode())
    except Exception:
        for rel in created:
            dest=root/rel
            if dest.is_file() and sha(dest.read_bytes())==sha(files[rel]):dest.unlink()
        raise
    print('Installed DevKit. No MES runtime files changed. Backup journal:',backup)


def do_rollback(root):
    backup=Path.home()/'.ipth_mes_updater_backups'/PATCH_ID
    f=backup/'journal.json'
    if not f.is_file():raise RuntimeError('DevKit installation journal not found')
    journal=json.loads(f.read_text())
    for rel in journal['created']:
        p=root/rel
        if not p.is_file() or sha(p.read_bytes())!=journal['files'][rel]:
            raise RuntimeError('File modified after install; refusing rollback: '+rel)
    for rel in journal['created']:(root/rel).unlink()
    archived=backup.with_name(backup.name+'.rolledback-'+dt.datetime.now(dt.timezone.utc).strftime('%Y%m%dT%H%M%SZ'))
    backup.rename(archived)
    print('Rolled back DevKit-owned files only; journal archived:', archived)


def main():
    p=argparse.ArgumentParser(description=__doc__)
    g=p.add_mutually_exclusive_group(required=True)
    g.add_argument('--scan',action='store_true')
    g.add_argument('--apply',action='store_true')
    g.add_argument('--rollback',action='store_true')
    p.add_argument('--root',type=Path)
    args=p.parse_args()
    root=root_from((args.root or Path.cwd()).resolve())
    if args.rollback:
        do_rollback(root)
        return
    files=load_files(root)
    states=classify(root, files)
    if args.scan:
        raise SystemExit(show(root, files, states))
    do_apply(root, files, states)

if __name__=='__main__':
    try:main()
    except (ValueError, RuntimeError, OSError, zipfile.BadZipFile) as exc:
        print('ERROR:',exc,file=sys.stderr)
        sys.exit(1)
